using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: Discriminator property renamed to "$type".
            // Opt back into the old name so existing 500K documents remain readable
            // and direct SQL queries (WHERE c.Discriminator = ...) keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: Id format changed from "EntityType|Key"
            // to just the raw key value. Opt back into the legacy format so existing
            // documents with id = "Product|123" are still found.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdValueGenerator>();

            // EF Core 9 breaking change #3: Cosmos DB indexes are no longer created
            // by EF Core; HasIndex is a no-op. Manage indexes via Azure Portal / IaC.
            // (Removed the previous HasIndex call.)
        });
    }
}

