class CosmosQuery
{
    // EF Core 9 breaking change #4: Synchronous I/O is no longer supported
    // on the Cosmos provider — calling .ToList() throws. Use async APIs.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we preserved "Discriminator"
        // property name via HasDiscriminator("Discriminator") in OnModelCreating.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // Use async instead of sync to avoid InvalidOperationException in EF 9
        var products = await ctx.Products
            .Where(p => p.Sku == "ABC")
            .ToListAsync();
    }
}

